css:
.print-format { padding:0; color:#1f2937; font-family:"Helvetica Neue",Helvetica,Arial,sans-serif; font-size:12px; }
* { -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; }
.ch { padding:7mm; }
.ch h2 { font-size:15px; font-weight:700; text-align:center; margin:0; }
.ch .sub { text-align:center; font-size:10px; color:#6b7280; margin:2px 0 10px; }
.ch .rule { height:3px; background:#1f2937; border:0; margin:6px 0 12px; }
.ch table { width:100%; border-collapse:collapse; }
.kv td { padding:5px 9px; border:1px solid #e5e7eb; vertical-align:top; }
.kv .k { background:#f9fafb; color:#6b7280; font-weight:600; width:22%; }
.kv .v { font-weight:600; color:#111827; }
.amt { width:100%; border-collapse:collapse; margin-top:12px; }
.amt td { padding:6px 10px; border-bottom:1px solid #eceef1; }
.amt td.n { text-align:right; font-variant-numeric:tabular-nums; }
.amt .tot td { font-weight:700; background:#1f2937; color:#fff; border:0; }
.ch .sec { font-size:10px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:#1f2937; margin:14px 0 6px; }
.ch .foot { margin-top:22px; font-size:11px; }
.badge { display:inline-block; padding:2px 8px; border-radius:9px; font-size:10px; font-weight:700; }
.badge.dep { background:#065f46; color:#fff; }
.badge.draft { background:#9ca3af; color:#fff; }
